    if (reset) begin
        counter <= 4'd0;
    end else begin
        if (state == 3'd0) begin
            counter <= 4'd0;
        end else if (state == 3'd1) begin
            if (counter < 3'd3) begin
                counter <= counter + 1;
            end
        end else if (state == 3'd2) begin
